result:
**The bug:** The comparison uses `<` (strictly less than), so when `decoded.exp === Math.floor(Date.now() / 1000)`, the condition is `false` and the expired token passes. The fix is `<=`.

**Second issue:** `jwt.verify()` already throws a `TokenExpiredError` for expired tokens, making the manual check dead code. The catch block swallows that distinction, returning the same generic error for both expired and malformed tokens.

Here's the fixed version:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    // jwt.verify() already rejects expired tokens (throws TokenExpiredError)
    // but the default clockTolerance is 0, so exp === now is correctly rejected
    const decoded = jwt.verify(token, process.env.JWT_SECRET);

    // Guard: reject tokens expiring at or before the current time
    // (handles edge case if called with { ignoreExpiration: true } elsewhere)
    if (decoded.exp <= Math.floor(Date.now() / 1000)) {
      return res.status(401).json({ error: 'Token expired' });
    }

    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    // Unexpected errors (e.g. missing JWT_SECRET) should not leak internals
    next(err);
  }
}

module.exports = authMiddleware;
```

Key changes:
- **`<=` instead of `<`** — tokens expiring exactly at the current second are now correctly rejected
- **`Math.floor()`** — avoids sub-second float drift in the comparison
- **Differentiated catch handling** — `TokenExpiredError` vs `JsonWebTokenError` give distinct responses; unexpected errors (like `process.env.JWT_SECRET` being undefined) are forwarded to your error-handling middleware instead of silently returning 401
